/* eslint-disable no-unused-vars */
/* eslint-disable jsx-a11y/img-redundant-alt */
import React, { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Howl } from 'howler';
import '../styles/PrankPage.css';

const PrankPage = () => {
  const [phase, setPhase] = useState('loading'); // loading, countdown, scare, reveal
  const [countdown, setCountdown] = useState(3);
  const [showConfetti, setShowConfetti] = useState(false);
  const soundRef = useRef(null);
  // const confettiRef = useRef(null);

  useEffect(() => {
    // 预加载音频
    soundRef.current = new Howl({
      src: [`${process.env.PUBLIC_URL}/sounds/scream.mp3`],
      preload: true,
      volume: 0.7
    });

    const timer1 = setTimeout(() => {
      setPhase('countdown');
      
      const countdownInterval = setInterval(() => {
        setCountdown(prev => {
          if (prev <= 1) {
            clearInterval(countdownInterval);
            triggerScare();
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    }, 2000);

    return () => {
      clearTimeout(timer1);
      if (soundRef.current) {
        soundRef.current.unload();
      }
    };
  }, []);

  const triggerScare = () => {
    // 播放音效
    if (soundRef.current) {
      soundRef.current.play();
    }

    // 震动效果
    if (navigator.vibrate) {
      navigator.vibrate([200, 100, 200, 100, 200]);
    }

    setPhase('scare');
    document.body.classList.add('shake');

    setTimeout(() => {
      document.body.classList.remove('shake');
      setPhase('reveal');
      setShowConfetti(true);
      
      // 彩带效果
      if (typeof window !== 'undefined' && window.confetti) {
        window.confetti({
          particleCount: 100,
          spread: 70,
          origin: { y: 0.6 }
        });
      }
    }, 3000);
  };

  const copyLink = () => {
    navigator.clipboard.writeText("https://6xbk6.github.io/prankmobileapp/");
    alert('链接已复制！快去整蛊你的朋友吧！😈');
  };

  return (
    <div className="prank-container">
      <AnimatePresence mode="wait">
        {phase === 'loading' && (
          <motion.div 
            key="loading"
            className="loading-screen"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <div className="loading-content">
              <div className="spinner"></div>
              <h2>正在为您准备惊喜...</h2>
              <p>请稍候，好东西值得等待 ✨</p>
            </div>
          </motion.div>
        )}

        {phase === 'countdown' && (
          <motion.div 
            key="countdown"
            className="countdown-screen"
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 1.2 }}
          >
            <h2>准备好接收你的奖品了吗？</h2>
            <motion.div 
              className="countdown-number"
              key={countdown}
              initial={{ scale: 0, rotate: -180 }}
              animate={{ scale: 1, rotate: 0 }}
              transition={{ type: "spring", stiffness: 200 }}
            >
              {countdown}
            </motion.div>
          </motion.div>
        )}

        {phase === 'scare' && (
          <motion.div 
            key="scare"
            className="scare-screen"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <motion.div 
              className="scare-content"
              initial={{ scale: 0.1 }}
              animate={{ scale: 1 }}
              transition={{ type: "spring", stiffness: 300, damping: 10 }}
            >
              <img src={`${process.env.PUBLIC_URL}/photos/scary.jpg`} alt="Scary Image" className="scary-image" />
            </motion.div>
          </motion.div>
        )}

        {phase === 'reveal' && (
          <motion.div 
            key="reveal"
            className="reveal-screen"
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
          >
            <div className="reveal-content">
              <h2>🎉 哈哈！你被整蛊了！ 🎉</h2>
              <p>恭喜你成功掉入陷阱！</p>
              
              <div className="stats">
                <div className="stat-item">
                  <span className="stat-number">😱</span>
                  <span className="stat-label">被吓到了吗？</span>
                </div>
                <div className="stat-item">
                  <span className="stat-number">🤣</span>
                  <span className="stat-label">开心一下</span>
                </div>
              </div>

              <div className="share-section">
                <h3>分享给朋友，一起快乐！</h3>
                <div className="share-link">
                  <input 
                    type="text" 
                    readOnly 
                    value="https://6xbk6.github.io/prankmobileapp/"
                    onClick={(e) => e.target.select()}
                  />
                  <button onClick={copyLink} className="copy-btn">
                    📋 复制链接
                  </button>
                </div>
              </div>

              {/* <button 
                className="restart-btn"
                onClick={() => window.location.href = '/'}
              >
                🔄 再来一次
              </button> */}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default PrankPage;