import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import '../styles/LandingPage.css';

const LandingPage = () => {
  const navigate = useNavigate();
  const [buttonText, setButtonText] = useState('🎁 领取神秘大奖');
  const [buttonPosition, setButtonPosition] = useState({ x: 0, y: 0 });
  const [clickCount, setClickCount] = useState(0);
  const [showRealButton, setShowRealButton] = useState(false);
  const [showParticles, setShowParticles] = useState(false);

  const dodgeTexts = [
    '🏃‍♂️ 别追我！',
    '😏 抓不到我吧',
    '🤪 再试试？',
    '😈 哈哈哈哈',
    '🎯 最后机会！'
  ];

  const handleButtonDodge = () => {
    if (clickCount < 5) {
      const maxX = window.innerWidth - 200;
      const maxY = window.innerHeight - 100;
      const newX = Math.random() * maxX;
      const newY = Math.random() * maxY;
      
      setButtonPosition({ x: newX, y: newY });
      setButtonText(dodgeTexts[clickCount]);
      setClickCount(prev => prev + 1);
      
      // 添加粒子效果
      setShowParticles(true);
      setTimeout(() => setShowParticles(false), 500);
    } else {
      setShowRealButton(true);
      setButtonText('🎊 好吧，点我进入');
    }
  };

  const handleRealButtonClick = () => {
    navigate('/surprise');
  };

  return (
    <div className="landing-container">
      <div className="background-animation"></div>
      
      <motion.div 
        className="content"
        initial={{ opacity: 0, y: 50 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8 }}
      >
        <h1 className="title">
          <span className="emoji">🎉</span>
          恭喜中奖！
          <span className="emoji">🎉</span>
        </h1>
        
        <p className="subtitle">
          你被选中获得价值 <span className="highlight">￥9999</span> 的神秘大奖！
        </p>
        
        <div className="features">
          <div className="feature-item">🏆 限时专享</div>
          <div className="feature-item">💎 价值连城</div>
          <div className="feature-item">🚀 立即领取</div>
        </div>
      </motion.div>

      {!showRealButton ? (
        <motion.button 
          className="dodge-button"
          style={{ 
            position: 'fixed',
            left: buttonPosition.x,
            top: buttonPosition.y,
            zIndex: 100
          }}
          onMouseEnter={handleButtonDodge}
          onTouchStart={handleButtonDodge}
          whileHover={{ scale: 1.1 }}
          whileTap={{ scale: 0.9 }}
        >
          {buttonText}
        </motion.button>
      ) : (
        <motion.button 
          className="real-button"
          onClick={handleRealButtonClick}
          initial={{ scale: 0 }}
          animate={{ scale: 1 }}
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
        >
          {buttonText}
        </motion.button>
      )}

      {showParticles && (
        <div className="particles">
          {[...Array(10)].map((_, i) => (
            <div key={i} className="particle"></div>
          ))}
        </div>
      )}
    </div>
  );
};

export default LandingPage;